INSERT INTO career_paths (career_name, description, interest_area) VALUES
  ('Frontend Developer', 'Builds the user-facing part of web applications: layouts, interactive components, accessibility and performance in the browser.', 'Web Development'),
  ('Backend Developer', 'Designs and implements server-side logic, APIs, databases and integrations that power applications.', 'Backend Development'),
  ('Full Stack Developer', 'Works across the whole web stack - from database and API to the user interface - and delivers features end to end.', 'Web Development'),
  ('Python Developer', 'Builds applications, services and automation in Python, commonly with web frameworks such as Flask or Django.', 'Backend Development'),
  ('Java Developer', 'Develops robust enterprise and backend applications on the Java platform, typically with Spring Boot.', 'Backend Development'),
  ('Data Analyst', 'Collects, cleans and analyses data to answer business questions and communicates the findings through reports and dashboards.', 'Data'),
  ('Data Scientist', 'Applies statistics and machine learning to data to build predictive models and generate insights.', 'AI/ML'),
  ('Machine Learning Engineer', 'Designs, trains, deploys and maintains machine learning models in production systems.', 'AI/ML'),
  ('NLP Engineer', 'Builds systems that process and understand human language, such as text classification, information extraction and search.', 'AI/ML'),
  ('DevOps Engineer', 'Automates building, testing, deployment and operation of software, bridging development and infrastructure.', 'DevOps'),
  ('Cloud Engineer', 'Designs, builds and operates secure, scalable infrastructure on cloud platforms.', 'Cloud'),
  ('QA Engineer', 'Ensures software quality by planning and executing tests, reporting defects and improving test processes.', 'Testing'),
  ('Automation Test Engineer', 'Builds and maintains automated test suites and integrates them into delivery pipelines.', 'Testing'),
  ('Cybersecurity Analyst', 'Protects systems and data by monitoring for threats, investigating incidents and reducing vulnerabilities.', 'Cybersecurity'),
  ('Mobile App Developer', 'Builds native or cross-platform applications for Android and iOS devices.', 'Mobile Development');
